/**
 * Milestone 5 against the real BDS 1.26.51.1 server on :19132 and the map server
 * on :3000, both already running.
 *
 * Walks the scenario from the milestone: existing terrain, new chunks generated by
 * the server, a surface-visible block change, players throughout, and BDS going
 * away. Everything is observed through the map's own HTTP API and rendered tiles,
 * and the map server's open files are checked to prove it never touches the live
 * database.
 */

import { execFile } from 'node:child_process';
import fs from 'node:fs/promises';
import { promisify } from 'node:util';
import { decode as decodePng } from '../node_modules/fast-png/lib/index.js';

const run = promisify(execFile);
const BASE = 'http://127.0.0.1:3000';
const WORLD = '/tmp/bds/worlds/Bedrock level';
const TMUX = ['-f', '/exec-daemon/tmux.portal.conf'];
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const failures = [];
let checks = 0;
function check(name, ok, detail = '') {
  checks++;
  console.log(`  ${ok ? 'ok  ' : 'FAIL'} ${name}${detail ? ` (${detail})` : ''}`);
  if (!ok) failures.push(name);
}

async function bds(command) {
  await run('tmux', [...TMUX, 'send-keys', '-t', 'bds-server:0.0', command, 'C-m']);
  console.log(`   > ${command}`);
}

const get = (path) => fetch(`${BASE}${path}`).then((response) => response.json());

async function tilePixels(chunk) {
  const info = await get('/api/map/info');
  const perTile = info.chunksPerTile;
  const tileX = Math.floor(chunk.x / perTile);
  const tileY = Math.floor(chunk.z / perTile);
  const response = await fetch(`${BASE}/tiles/overworld/0/${tileX}/${tileY}.png?v=${info.version}`);
  const tile = decodePng(new Uint8Array(await response.arrayBuffer()));
  const originX = (chunk.x - tileX * perTile) * 16;
  const originZ = (chunk.z - tileY * perTile) * 16;
  const pixels = [];
  for (let z = 0; z < 16; z++) {
    for (let x = 0; x < 16; x++) {
      const offset = ((originZ + z) * tile.width + originX + x) * tile.channels;
      pixels.push([tile.data[offset], tile.data[offset + 1], tile.data[offset + 2], tile.data[offset + 3]]);
    }
  }
  return pixels;
}

const differing = (a, b) =>
  a.filter((pixel, i) => JSON.stringify(pixel.slice(0, 3)) !== JSON.stringify(b[i].slice(0, 3))).length;

/** Polls the map state until `done` is happy, reporting how long it took. */
async function waitFor(label, done, timeoutMs = 150000) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    const state = await get('/api/map/state');
    if (await done(state)) return { state, waitedMs: Date.now() - started };
    await sleep(1000);
  }
  return { state: await get('/api/map/state'), waitedMs: Date.now() - started, timedOut: true };
}

/** A chunk near the world spawn that the map draws in full. */
async function drawnChunkNearSpawn() {
  for (let radius = 0; radius <= 6; radius++) {
    for (let z = -radius; z <= radius; z++) {
      for (let x = -radius; x <= radius; x++) {
        const pixels = await tilePixels({ x, z });
        if (pixels.filter((pixel) => pixel[3] === 255).length === 256) return { x, z };
      }
    }
  }
  throw new Error('no fully drawn chunk near the world spawn');
}

if (process.env.RESTART_MAP !== '0') {
  console.log('0. restarting the map server so this run starts from map version 1');
  await run('tmux', [...TMUX, 'send-keys', '-t', 'map-server:0.0', 'C-c']);
  await sleep(3000);
  await run('tmux', [
    ...TMUX,
    'send-keys',
    '-t',
    'map-server:0.0',
    'clear; rm -rf /tmp/m5-live-cache; WORLD_PATH="/tmp/bds/worlds/Bedrock level" MAP_CACHE=/tmp/m5-live-cache ' +
      'PORT=3000 WORLD_REFRESH_INTERVAL=30000 API_KEY=milestone4-test-key npm start 2>&1 | tee /tmp/m5-map-server.log',
    'C-m',
  ]);
  for (let attempt = 0; attempt < 120; attempt++) {
    const ok = await fetch(`${BASE}/api/map/info`).then((response) => response.ok).catch(() => false);
    if (ok) break;
    await sleep(1000);
  }
}

console.log('\n1. the map is serving the world BDS has open');
const start = await get('/api/map/info');
const startState = await get('/api/map/state');
const reference = await drawnChunkNearSpawn();
{
  const players = await get('/api/players');
  console.log(
    `   world ${start.world.name} (${start.world.version}), ${start.chunkCount} chunks, ` +
      `extent X ${start.blockBounds.minX}..${start.blockBounds.maxX} Z ${start.blockBounds.minZ}..${start.blockBounds.maxZ}`,
  );
  check('existing terrain renders', true, `chunk ${reference.x},${reference.z} is fully drawn`);
  check('the map version starts at 1', startState.version === 1, String(startState.version));
  check('players are being tracked', players.players.length > 0 && !players.stale, JSON.stringify(players.players));
}

console.log('\n2. the map server never opens the live database');
{
  // The node process itself, not the npm/sh wrapper around it.
  const { stdout: pids } = await run('pgrep', ['-f', 'node.*server/index.ts']);
  const candidates = pids.trim().split('\n');
  let pid = null;
  for (const candidate of candidates) {
    const cmdline = await fs.readFile(`/proc/${candidate}/cmdline`, 'utf8').catch(() => '');
    if (cmdline.includes('node') && cmdline.includes('server/index.ts')) pid = candidate;
  }
  check('found the map server process', pid !== null, `pids ${candidates.join(',')} -> ${pid}`);

  const links = [];
  for (const fd of await fs.readdir(`/proc/${pid}/fd`)) {
    const target = await fs.readlink(`/proc/${pid}/fd/${fd}`).catch(() => null);
    if (target) links.push(target);
  }
  const live = links.filter((target) => target.startsWith(WORLD));
  const snapshotHandles = links.filter((target) => target.includes('world-snapshot'));
  check('no open file handle inside the live world', live.length === 0, live.join(', ') || 'none');
  check(
    'it holds the snapshot copy open instead',
    snapshotHandles.length > 0,
    `${snapshotHandles.length} handles, e.g. ${snapshotHandles[0] ?? 'none'}`,
  );
  const { stdout: locks } = await run('bash', ['-c', `grep -c "bds/worlds" /proc/${pid}/maps || true`]);
  check('no mapped file from the live world either', locks.trim() === '0', `matches: ${locks.trim()}`);
}

console.log('\n3. BDS generates terrain in an unexplored area');
{
  // A free ticking-area slot, then a new area far outside the mapped extent.
  for (const name of ['m5new', 'm5fresh']) {
    await bds(`tickingarea remove ${name}`);
    await sleep(1500);
  }
  // Well outside anything the map has seen, so these chunks really are new.
  const fresh = {
    x: Number(process.env.FRESH_X ?? start.blockBounds.maxX + 600),
    z: Number(process.env.FRESH_Z ?? start.blockBounds.maxZ + 600),
  };
  console.log(`   generating around ${fresh.x},${fresh.z}, outside the mapped extent`);
  await bds(`tickingarea add ${fresh.x} 0 ${fresh.z} ${fresh.x + 150} 128 ${fresh.z + 150} m5fresh`);

  const grown = await waitFor(
    'new chunks',
    (state) => state.blockBounds.maxX > start.blockBounds.maxX && state.blockBounds.maxZ > start.blockBounds.maxZ,
  );
  check(
    'the mapped extent grew to cover the new area',
    !grown.timedOut,
    `X ..${grown.state.blockBounds.maxX}, Z ..${grown.state.blockBounds.maxZ} after ${Math.round(grown.waitedMs / 1000)} s`,
  );
  check(
    'the map version moved with it',
    grown.state.version > startState.version,
    `version ${startState.version} -> ${grown.state.version}`,
  );
  check(
    'the chunk count grew',
    grown.state.chunkCount > start.chunkCount,
    `${start.chunkCount} -> ${grown.state.chunkCount}`,
  );

  // BDS writes the new chunks out gradually, so ask which of them the map can
  // draw rather than betting on one particular chunk.
  const area = [];
  for (let z = Math.floor(fresh.z / 16); z <= Math.floor((fresh.z + 150) / 16); z++) {
    for (let x = Math.floor(fresh.x / 16); x <= Math.floor((fresh.x + 150) / 16); x++) area.push({ x, z });
  }
  const drawnChunks = async () => {
    let drawn = 0;
    for (const chunk of area) {
      const pixels = await tilePixels(chunk);
      if (pixels.filter((pixel) => pixel[3] === 255).length > 200) drawn++;
    }
    return drawn;
  };
  const rendered = await waitFor('new area rendered', async () => (await drawnChunks()) >= 4, 90000);
  const drawn = await drawnChunks();
  check(
    'the newly generated area renders as terrain',
    drawn >= 4,
    `${drawn} of ${area.length} chunks around ${fresh.x},${fresh.z} are fully drawn after ` +
      `${Math.round((grown.waitedMs + rendered.waitedMs) / 1000)} s`,
  );
  const players = await get('/api/players');
  check('players kept coming through the refresh', !players.stale, JSON.stringify(players.players));
}

console.log('\n4. a surface-visible block change in an already mapped chunk');
const platform = { chunk: { x: 24, z: 9 }, y: 120 };
{
  const blockX = platform.chunk.x * 16;
  const blockZ = platform.chunk.z * 16;
  const before = await tilePixels(platform.chunk);
  const versionBefore = (await get('/api/map/state')).version;

  await bds(`fill ${blockX} ${platform.y} ${blockZ} ${blockX + 15} ${platform.y} ${blockZ + 15} snow`);
  const placed = await waitFor('snow platform', async (state) => {
    if (state.version === versionBefore) return false;
    return differing(await tilePixels(platform.chunk), before) > 200;
  });
  check(
    'the placed blocks show up on the map',
    !placed.timedOut,
    `${differing(await tilePixels(platform.chunk), before)}/256 pixels changed after ${Math.round(placed.waitedMs / 1000)} s`,
  );

  const withSnow = await tilePixels(platform.chunk);
  check(
    'the new surface is drawn as snow',
    withSnow.filter((pixel) => pixel[0] > 220 && pixel[1] > 220 && pixel[2] > 220).length > 200,
    `${withSnow.filter((pixel) => pixel[0] > 220 && pixel[1] > 220 && pixel[2] > 220).length}/256 pixels are near-white`,
  );

  await bds(`fill ${blockX} ${platform.y} ${blockZ} ${blockX + 15} ${platform.y} ${blockZ + 15} air`);
  const removed = await waitFor('snow removed', async () => differing(await tilePixels(platform.chunk), before) < 20);
  check(
    'removing the blocks puts the terrain back',
    !removed.timedOut,
    `${differing(await tilePixels(platform.chunk), before)}/256 pixels differ from the original after ` +
      `${Math.round(removed.waitedMs / 1000)} s`,
  );
}

console.log('\n5. players while all of that was going on');
{
  const first = await get('/api/players');
  await bds('scriptevent bmap:patrol');
  await sleep(8000);
  const second = await get('/api/players');
  const moved =
    first.players[0] && second.players[0] &&
    (first.players[0].x !== second.players[0].x || first.players[0].z !== second.players[0].z);
  check('the tracked player is still moving', Boolean(moved), `${JSON.stringify(first.players[0])} -> ${JSON.stringify(second.players[0])}`);
  check('player data is not stale', second.stale === false, `updatedAt ${second.updatedAt}`);
  await bds('scriptevent bmap:stop');
}

console.log('\n6. BDS stops');
{
  await bds('stop');
  await sleep(15000);
  const players = await get('/api/players');
  check('players go stale once updates stop', players.stale === true && players.players.length === 0, JSON.stringify(players));
  const state = await get('/api/map/state');
  check('the terrain map keeps serving', state.chunkCount > start.chunkCount, `${state.chunkCount} chunks`);
  const pixels = await tilePixels(reference);
  check(
    'tiles still render with BDS gone',
    pixels.filter((pixel) => pixel[3] === 255).length === 256,
    `chunk ${reference.x},${reference.z}`,
  );
  // The first refresh after a shutdown still sees BDS flushing its last writes;
  // the one after that has an idle world to look at.
  const idle = await waitFor('an idle refresh', (current) => current.lastRefresh?.sourceChanged === false, 120000);
  const after = idle.state;
  check('and a refresh against a stopped server is harmless', after.chunkCount >= state.chunkCount, `${after.chunkCount} chunks`);
  const last = after.lastRefresh;
  check(
    'with nothing writing, a refresh costs almost nothing',
    last.sourceChanged === false && last.totalMs < 20,
    `sourceChanged ${last.sourceChanged}, ${last.totalMs.toFixed(2)} ms`,
  );
}

console.log('\nthe map server log for this run:');
{
  const log = await fs.readFile('/tmp/m5-map-server.log', 'utf8');
  for (const line of log.split('\n').filter((line) => /terrain (updated|refresh)|world files/.test(line))) {
    console.log(`   ${line}`);
  }
}

console.log(`\n${checks - failures.length}/${checks} checks passed`);
if (failures.length) console.log('failed:', failures.join('; '));
